"""Build portable review pages from the checked-in operating records."""
import csv
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1] / 'docs/travel/business'
def read(name): return json.loads((ROOT/f'{name}.json').read_text())
def esc(value): return html.escape(str(value))
STYLE = '''<style>:root{color-scheme:light;--ink:#12383c;--paper:#f4f1e8;--accent:#b65023}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.6 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:30px 22px 80px}header{border-bottom:1px solid #c7cec6;padding:18px 0;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}h1{font-size:clamp(38px,7vw,78px);line-height:1.05;letter-spacing:-.04em;max-width:900px;margin:44px 0 20px}h2{font-size:29px;margin-top:40px}h3{margin-top:0}p{max-width:800px}.eyebrow{font-size:13px;letter-spacing:.14em;text-transform:uppercase;color:var(--accent);font-weight:800}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.card{background:white;border:1px solid #d1d7cd;border-radius:16px;padding:24px}.value{font-size:44px;font-weight:750;letter-spacing:-.04em}.notice{border-left:5px solid var(--accent);padding:16px 22px;background:#fff4dc;border-radius:0 12px 12px 0}.muted{color:#526366;font-size:14px}a{color:#85401e;overflow-wrap:anywhere}button,.button{display:inline-block;padding:12px 18px;border:0;border-radius:8px;background:var(--ink);color:white;font:inherit;text-decoration:none;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}input,select{font:inherit;padding:9px;border:1px solid #9ba9a6;border-radius:6px;max-width:100%;width:100%}label{display:block;font-size:14px;font-weight:650;margin-bottom:14px}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;vertical-align:top;padding:12px;border-bottom:1px solid #c7cec6;min-width:120px}th{background:#e4e9e0}summary{cursor:pointer;font-weight:700}video{width:100%;max-width:340px;border-radius:16px;background:#12383c}footer{margin-top:50px;border-top:1px solid #c7cec6;padding-top:20px;font-size:13px}nav{display:flex;gap:15px;flex-wrap:wrap}@media(max-width:480px){main{padding:18px 16px 50px}.card{padding:18px}h1{margin-top:30px}.value{font-size:36px}}</style>'''
def page(title, body, script=''):
    return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+title+'</title>'+STYLE+'<main><header><b>ALEX TRAVELDECODED</b><span class="eyebrow">Private review • 8 Nov 2026</span></header>'+body+'<footer>Research snapshot. No public publishing, checkout, email collection or affiliate tracking is active. Recheck all prices before travel.</footer></main>'+script+'</html>'
def main():
    ledger=read('ledger'); cal=read('calendar'); affiliates=read('affiliates')
    pricecards=''.join('<article class="card"><span class="eyebrow">'+esc(p['city'])+'</span><h3>'+esc(p['provider'])+'</h3><div class="value">'+esc(p['currency'])+' '+esc(p['local_price'])+'</div><p>'+esc(p['unit'])+' · '+esc(p['eligibility'])+'</p><p class="muted">'+esc(p['notes'])+'</p><a href="'+esc(p['source_url'])+'">Official price source</a></article>' for p in ledger['prices'])
    body='''<p class="eyebrow">Singapore → Bangkok / Field notes 001</p><h1>A fair comparison starts with the right price.</h1><p>Our first Bangkok research review looks at admission eligibility and the exchange conditions that can change a travel budget.</p><div class="notice"><b>The complete S$50 basket is not ready.</b> Food, comparable transport and a qualifying S$50 cash exchange quote still need verification. No saving or winning city is claimed.</div><h2>Watch the research review</h2><video controls preload="metadata" poster="cover.png"><source src="TravelDecoded_Bangkok_Research_Review.mp4" type="video/mp4"></video><p class="muted">51-second English narration with timed captions. Review draft, not approved for publication. Video file is included in the download bundle.</p><h2>Prices with their conditions</h2><p>Checked 8 November 2026. These are separate experiences, not matched products or a cost-of-living index.</p><div class="cards">'''+pricecards+'''</div><h2>Why there is no baht conversion yet</h2><p>The detailed Saleem Exchange Centre listing shows a S$300 minimum. Fees are unconfirmed, and the retrieved page contains conflicting duplicate values. We cannot scale that quote down and call it an executable S$50 exchange.</p><p><a href="https://cashchanger.co/singapore/mc/saleem-exchange-centre/110">Review the exchange listing</a> · <a href="ledger.json" download>Download the full source register</a></p><h2>Take the research notes</h2><a class="button" href="Bangkok_Comparison_Research_Notes.pdf" download>Download free research notes</a><p class="muted">A dated research preview, not the complete city budget guide. No email required in this private build.</p><h2>Booking tools, when approved</h2><div class="cards">'''+''.join('<article class="card"><h3>'+x+'</h3><p>No approved affiliate account is connected.</p><button disabled>Not active</button></article>' for x in ['Accommodation','Attractions','Transport','Travel eSIM'])+'''</div><p><b>Disclosure:</b> No affiliate links are active. Future qualifying links will be visibly disclosed and will not affect the factual comparison.</p><h2>Three days in Bangkok • S$19 proposed</h2><p>The paid guide is planned. Route checks, maps, transport instructions, spending estimates, a budget tracker and a customer refund policy must be completed before sale.</p><button disabled>Not available for purchase</button><p><a href="dashboard.html">Open the operating dashboard</a></p>'''
    (ROOT/'bangkok.html').write_text(page('Bangkok research | Alex TravelDecoded',body))
    data={n:read(n) for n in ['ledger','calendar','affiliates','status','products','competitors']}
    script='''<script>const DATA=__DATA__;
const defaults={conservative:[400,.004,.005,.15,.015,.65,0],base:[2000,.008,.01,.20,.02,.75,0],upside:[8000,.015,.02,.25,.03,.8,1]};
const fields={videos_month:["Videos per month",13],views_video:["Views per video across all platforms",2000],view_site:["Views to website fraction",.008],site_sale:["Website to guide sale fraction",.01],site_affiliate:["Website to affiliate click fraction",.2],click_booking:["Clicks to recorded booking fraction",.02],completion:["Bookings completed fraction",.75],commission:["Commission per completed booking S$",8],guide_price:["Guide price S$",19],refund_rate:["Guide refunds fraction",.05],payment_pct:["Payment fee fraction (placeholder)",.06],payment_fixed:["Payment fee per sale S$ (placeholder)",.5],guide_paid_share:["Net guide revenue paid fraction",.9],affiliate_paid_share:["Earned commission paid fraction",.25],b2b_month:["B2B customers per month",0],b2b_price:["B2B price S$",450],b2b_cost:["B2B direct cost per customer S$",150],b2b_paid_share:["B2B revenue paid fraction",.5],software_month:["Monthly software S$",0],compliance_month:["Monthly compliance costs S$",0]};
const fractionKeys=Object.keys(fields).filter(k=>/share|rate|pct/.test(k)||['view_site','site_sale','site_affiliate','click_booking','completion'].includes(k));
const assumptions=document.getElementById('assumptions');Object.entries(fields).forEach(([k,[label,v]])=>{let l=document.createElement('label');l.textContent=label;let i=document.createElement('input');i.id=k;i.type='number';i.min=0;i.step='any';if(fractionKeys.includes(k))i.max=1;i.value=v;i.oninput=render;l.append(i);assumptions.append(l)});
function values(){return Object.fromEntries(Object.keys(fields).map(k=>[k,Number(document.getElementById(k).value)]))}
function forecast(a,m){const views=a.videos_month*a.views_video*m,visits=views*a.view_site,sales=visits*a.site_sale,clicks=visits*a.site_affiliate,bookings=clicks*a.click_booking,completed=bookings*a.completion,affiliate=completed*a.commission,gross=sales*a.guide_price,refunds=gross*a.refund_rate,fees=gross*a.payment_pct+sales*a.payment_fixed,b2b=a.b2b_month*m*a.b2b_price,costs=m*(a.software_month+a.compliance_month+a.b2b_month*a.b2b_cost),cash=(gross-refunds)*a.guide_paid_share+affiliate*a.affiliate_paid_share+b2b*a.b2b_paid_share;return {views,visits,sales,clicks,bookings,completed,affiliate,paid:affiliate*a.affiliate_paid_share,contribution:gross-refunds+affiliate+b2b-fees-costs,cash,netcash:cash-fees-costs}}
const fmt=n=>n.toLocaleString('en-SG',{maximumFractionDigits:2});
function table(headers,rows){return '<div class="tablewrap"><table><thead><tr>'+headers.map(x=>'<th>'+safe(x)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+safe(x)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'}
function safe(x){let d=document.createElement('div');d.textContent=x??'Unavailable';return d.innerHTML}
function render(){const a=values();if(Object.keys(fields).some(k=>!Number.isFinite(a[k])||a[k]<0)||fractionKeys.some(k=>a[k]>1)){document.getElementById('forecast').textContent='Use non-negative inputs and fractions between 0 and 1.';return}document.getElementById('forecast').innerHTML=table(['Period','Views','Guide sales','Completed bookings','Earned commission S$','Paid commission S$','Contribution S$','Cash received S$','Net cash S$'],[[1,'30 days'],[3,'90 days'],[6,'6 months'],[12,'12 months']].map(([m,label])=>{let f=forecast(a,m);return [label,...[f.views,f.sales,f.completed,f.affiliate,f.paid,f.contribution,f.cash,f.netcash].map(fmt)]}));const guide=a.guide_price*(1-a.refund_rate-a.payment_pct)-a.payment_fixed,b2b=a.b2b_price-a.b2b_cost,fixed=a.software_month+a.compliance_month;document.getElementById('targets').innerHTML=table(['Monthly contribution target','Guide sales only','Completed bookings only','B2B clients only'],[500,1000,3000,5000].map(t=>['S$'+t,...[guide,a.commission,b2b].map(u=>u>0?Math.ceil((t+fixed)/u):'Not achievable')]));window.currentForecast=a}
document.getElementById('scenario').onchange=e=>{let v=defaults[e.target.value];['views_video','view_site','site_sale','site_affiliate','click_booking','completion','b2b_month'].forEach((k,i)=>document.getElementById(k).value=v[i]);render()};
function download(name,obj){let u=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
document.getElementById('export').onclick=()=>download('traveldecoded-assumptions.json',values());document.getElementById('records').onclick=()=>download('traveldecoded-registers.json',DATA);
document.getElementById('import').onchange=async e=>{try{let a=JSON.parse(await e.target.files[0].text());for(let k of Object.keys(fields)){if(!(k in a)||typeof a[k]!=='number'||!Number.isFinite(a[k])||a[k]<0||(fractionKeys.includes(k)&&a[k]>1))throw Error('Invalid or missing '+k)}for(let k of Object.keys(fields))document.getElementById(k).value=a[k];render();document.getElementById('importstatus').textContent='Imported.'}catch(err){document.getElementById('importstatus').textContent=err.message}};
document.getElementById('calendar').innerHTML=table(['ID','Singapore publication time','Title','Research','Video'],DATA.calendar.map(r=>[r.id,r.publish_at.replace('T',' ').replace('+08:00',' SGT'),r.title,r.research_status,r.video_status]));
document.getElementById('affiliates').innerHTML=table(['Programme','Approval','Commission basis','Eligibility'],DATA.affiliates.map(r=>[r.programme||r.name||r.programme_name,r.approval_status,r.commission_basis,r.singapore_eligibility]));render();</script>'''.replace('__DATA__',json.dumps(data).replace('</','<\\/'))
    body='''<nav><a href="#finance">Forecast</a><a href="#calendar">Calendar</a><a href="#affiliates">Affiliates</a><a href="bangkok.html">Bangkok page</a></nav><h1>Build trust.<br>Then measure revenue.</h1><p>Operating snapshot for the proposed 25 November 2026 launch. These records are editable exports, not live connected platform analytics.</p><div class="cards"><article class="card"><span class="eyebrow">Production</span><div class="value">1 review</div><p>51-second narrated draft; full basket pilot blocked.</p></article><article class="card"><span class="eyebrow">Publishing</span><div class="value">39 slots</div><p>13 weeks. None approved or published.</p></article><article class="card"><span class="eyebrow">Actual revenue</span><div class="value">Unknown</div><p>No account reporting connected. Not assumed zero.</p></article></div><h2>Release blockers</h2><div class="notice">Qualifying retail S$50 exchange quote, food and transport basket, complete guide, account approvals and commercial readiness checks remain outstanding.</div><p><a href="ledger.json" download>Pricing ledger JSON</a> · <a href="prices.csv" download>Pricing CSV</a> · <a href="OPERATIONS.md">Setup and recovery</a></p><button id="records">Export all registers</button><section id="finance"><h2>Financial model</h2><p>All rates below are explicit hypotheses, not industry benchmarks. Monthly steady-state inputs are multiplied by 1, 3, 6 and 12. Platform advertising revenue stays at zero. Expected fractional sales are modelling outputs, not actual transactions.</p><label>Scenario<select id="scenario"><option value="base">Base</option><option value="conservative">Conservative</option><option value="upside">Upside</option></select></label><details><summary>Edit assumptions</summary><div class="cards" id="assumptions"></div></details><p><button id="export">Export assumptions</button></p><label>Import saved assumptions<input type="file" id="import" accept="application/json"></label><p id="importstatus" role="status"></p><div id="forecast"></div><p class="muted">Fees are conservative placeholders, not verified provider terms. Paid shares are simplified settlement assumptions, not a dated receivables schedule. Income tax, owner labour and any unentered business costs are excluded. Net cash assumes entered costs and fees are paid in the period. Replace every assumption with actual data as it becomes available.</p><h3>Sales needed for contribution targets</h3><div id="targets"></div><p class="muted">Each column is a separate single-stream scenario, including the entered fixed monthly costs. Guide margin deducts refunds and payment fees; B2B margin deducts direct cost. Affiliate bookings must be completed and commission earned. These targets are contribution, not cash-in-bank or take-home pay.</p></section><h2>39-slot publishing calendar</h2><p>Wednesday and Friday 19:30; Sunday 12:30, Singapore time. Proposed test schedule; user approval required for every video.</p><div id="calendar"></div><h2>Competitor research</h2><p>20 relevant businesses identified from their public sites. Short-form playback analysis, engagement and conversion evidence remain outstanding.</p><p><a href="competitors.json" download>Download competitor register</a></p><h2>Affiliate approval tracker</h2><p>29 programmes. Public headline terms are partial research only. Blank values mean unverified; no tracking link has been created.</p><div id="affiliates"></div>'''
    (ROOT/'dashboard.html').write_text(page('Operating dashboard | Alex TravelDecoded',body,script))
    with (ROOT/'prices.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(ledger['prices'][0]));w.writeheader();w.writerows(ledger['prices'])
    print('Built bangkok.html, dashboard.html and prices.csv')

if __name__=='__main__': main()
